# ML: learn to classify by example
seen = {"t-shirt": "small", "jeans": "large", "sock": "small"}
new = "shirt"
if new in seen:
    print(f"{new} → {seen[new]}")
else:
    print(f"{new} → predicting 'small' by similarity")

# RL: find best action by reward
rewards = {"sit": 5, "stay": 3, "jump": -1}
best = max(rewards, key=rewards.get)
for a, r in rewards.items():
    print(f"{a}: reward {r}")
print(f"Learned: {best} is best")
